#ifndef OPTIONS_DEFS_H
#define OPTIONS_DEFS_H 1

#define BINOMIAL_NUM 64

#endif // OPTIONS_DEFS_H

#include <algorithm>
#include <math.h>
#include <cstdint>
#include <cstring>
#include <cmath>
#include <omp.h>

// Cumulative normal distribution function
static inline float CND(float X) {
    float L = fabsf(X);

    float k = 1.f / (1.f + 0.2316419f * L);
    float k2 = k * k;
    float k3 = k2 * k;
    float k4 = k2 * k2;
    float k5 = k3 * k2;

    const float invSqrt2Pi = 0.39894228040f;
    float w = (0.31938153f * k - 0.356563782f * k2 + 1.781477937f * k3 + -1.821255978f * k4 + 1.330274429f * k5);
    w *= invSqrt2Pi * expf(-L * L * .5f);

    if (X > 0.f)
        w = 1.f - w;
    return w;
}

void black_scholes_serial(float Sa[], float Xa[], float Ta[], float ra[], float va[], float result[], int count) {
    for (int i = 0; i < count; ++i) {
        float S = Sa[i], X = Xa[i];
        float T = Ta[i], r = ra[i];
        float v = va[i];

        float d1 = (logf(S / X) + (r + v * v * .5f) * T) / (v * sqrtf(T));
        float d2 = d1 - v * sqrtf(T);

        result[i] = S * CND(d1) - X * expf(-r * T) * CND(d2);
    }
}

void binomial_put_serial(float Sa[], float Xa[], float Ta[], float ra[], float va[], float result[], int count) {
    float V[BINOMIAL_NUM];

    for (int i = 0; i < count; ++i) {
        float S = Sa[i], X = Xa[i];
        float T = Ta[i], r = ra[i];
        float v = va[i];

        float dt = T / BINOMIAL_NUM;
        float u = expf(v * sqrtf(dt));
        float d = 1.f / u;
        float disc = expf(r * dt);
        float Pu = (disc - d) / (u - d);

        for (int j = 0; j < BINOMIAL_NUM; ++j) {
            float upow = powf(u, (float)(2 * j - BINOMIAL_NUM));
            V[j] = std::max(0.f, X - S * upow);
        }

        for (int j = BINOMIAL_NUM - 1; j >= 0; --j)
            for (int k = 0; k < j; ++k)
                V[k] = ((1 - Pu) * V[k] + Pu * V[k + 1]) / disc;

        result[i] = V[0];
    }
}

extern "C" void run(const void* input1, const void* input2, void* output, int n, int parameter, int threads) {
    if (n <= 0)
        return;

    float* a = (float*)input1;
    float* result = (float*)output;
    const int requested_threads = threads > 0 ? threads : 1;
    const int team_size = std::min(requested_threads, n);

    if (n < 128 || team_size == 1) {
        binomial_put_serial(a, a + n, a + 2 * n, a + 3 * n, a + 4 * n, result, n);
        return;
    }

    // Assign each worker one contiguous range, using the actual team size so
    // runtime limits or dynamic team reduction cannot leave elements unwritten.
    #pragma omp parallel num_threads(team_size)
    {
        const int worker_count = omp_get_num_threads();
        const int worker_id = omp_get_thread_num();
        const int begin = static_cast<int>((static_cast<std::int64_t>(n) * worker_id) / worker_count);
        const int end = static_cast<int>((static_cast<std::int64_t>(n) * (worker_id + 1)) / worker_count);

        for (int i = begin; i < end; ++i) {
            float V[BINOMIAL_NUM];
            float S = a[i], X = a[n + i];
            float T = a[2 * n + i], r = a[3 * n + i];
            float v = a[4 * n + i];

            float dt = T / BINOMIAL_NUM;
            float u = expf(v * sqrtf(dt));
            float d = 1.f / u;
            float disc = expf(r * dt);
            float Pu = (disc - d) / (u - d);

            for (int j = 0; j < BINOMIAL_NUM; ++j) {
                float upow = powf(u, (float)(2 * j - BINOMIAL_NUM));
                V[j] = std::max(0.f, X - S * upow);
            }

            for (int j = BINOMIAL_NUM - 1; j >= 0; --j)
                for (int k = 0; k < j; ++k)
                    V[k] = ((1 - Pu) * V[k] + Pu * V[k + 1]) / disc;

            result[i] = V[0];
        }
    }
}
